Let $f$ be a complex-valued harmonic function on the unit disc $\mathbb{D}$ given by 
		\begin{center}
			$f(z)=h(z)+\overline{g(z)}  $  
		\end{center}
		where $h(z)=\sum_{n=0}^{\infty} a_{n}z^{n}$ and $g(z)=\sum_{n=0}^{\infty} {b_{n}z^{n}}$ are analytic. Suppose \begin{center}
			$\mathnormal{H}_{h}^{2}(\mathbb{D})= \lbrace f:\mathbb{D} \rightarrow \mathbb{C}: f(z)= \sum_{n=0}^{\infty} a_{n}z^{n} + \sum_{n=0}^{\infty} \overline{b_{n}z^{n}}$ with $\sum_{n=0}^{\infty} |a_{n}|^{2}+|b_{n}|^{2} <\infty \rbrace$.
		\end{center} 	
		Then $||.||_{\mathnormal{H}_{h}^{2}}: {\mathnormal{H}_{h}^{2}}(\mathbb{D}) \rightarrow \mathbb{R}$  defined by $||f||_{\mathnormal{H}_{h}^{2}}=({\sum_{n=0}^{\infty}|a_{n}|^{2} + |b_{n}|^{2}})^{\frac{1}{2}}$ is a norm.

The norm defined on $\mathnormal{H}_{h}^{2}$ (in Theorem 2.1) has another equivalent representation by integral means which is denoted by $\mathnormal{M}_{2}^{2} (f,r)$ and defined by 
		\begin{center}
			$\mathnormal{M}_{2}^{2} (f,r) = \frac{1}{2\pi} \int_{-\pi}^{\pi} |f(re^{i\theta})|^{2} d\theta$,
		\end{center}
		where $f(z)=\sum_{n=0}^{\infty} a_{n}{z}^{n}+\sum_{n=0}^{\infty} \overline{ b_{n}{z}^{n}}$ on $\mathbb{D}$ and $0 \leq r < 1$.

Now using polar form of the series representation of $f$, we get
		\begin{center}
			$ f(re^{i\theta} )=\sum_{n=0}^{\infty} a_{n}{r}^{n}{e^{in\theta}}+\sum_{n=0}^{\infty} \overline{ b_{n}{r}^{n}{e^{in\theta}}}$.
		\end{center}
		After some algebraic manipulation, we obtain 
		\begin{center}
			$ |f(re^{i\theta})|^{2}=\sum_{n=0}^{\infty} \sum_{m=0}^{\infty} a_{n}\overline{a_{m}}{r}^{n+m}{e^{i(n-m)\theta}} +\sum_{n=0}^{\infty}\sum_{m=0}^{\infty} a_{m}b_{n}{r}^{m+n}{e^{i(n+m)\theta}} + \sum_{n=0}^{\infty}\sum_{m=0}^{\infty}\overline{ a_{m}b_{n}{r}^{m+n}{e^{i(n+m)\theta}}}+\sum_{n=0}^{\infty} \sum_{m=0}^{\infty} b_{m}\overline{b_{n}}{r}^{n+m}{e^{i(n-m)\theta}}$. 
		\end{center}
		It is clear that the integral of exponential function $\lbrace e^{in\theta} \rbrace_{n=0}^{\infty}$ is $2\pi$ when $n=m$ and $0$ when $n \neq m$. Multiplying both sides of the above equation by $\frac{1}{2\pi}$ and integrating with respect to $\theta$ from $-\pi $ to $\pi$, we get 
		\begin{center}
			$ \frac{1}{2\pi}\int_{-\pi}^{\pi}|f(re^{i\theta})|^{2} d\theta=\sum_{n=0}^{\infty} |a_{n}|^{2}{r}^{2n} +\sum_{n=0}^{\infty} |b_{n}|^{2}{r}^{2n} +\frac{1}{2\pi}\int_{-\pi}^{\pi} \sum_{n=0}^{\infty}\sum_{n=0}^{\infty} 2\Re ({a_{n}b_{n}{r}^{2n}{e^{2in\theta}}})d\theta $
		\end{center}
		\begin{center}
			$=\sum_{n=0}^{\infty} (|a_{n}|^{2} + |b_{n}|^{2}){r}^{2n} + \sum_{n=0}^{\infty}\sum_{n=0}^{\infty} \frac{2{r}^{2n}}{2\pi} \Re ({a_{n}b_{n}\int_{-\pi}^{\pi} {e^{2in\theta}}}d\theta)$
		\end{center}
		\begin{center}
			$=\sum_{n=0}^{\infty} (|a_{n}|^{2} + |b_{n}|^{2}){r}^{2n}$ \hspace{6mm} 
		\end{center} 
		Therefore,
		\begin{center}
			$M_{2}^{2} (f,r)=\frac{1}{2\pi}\int_{-\pi}^{\pi}|f(re^{i\theta})|^{2}d\theta=\sum_{n=0}^{\infty} (|a_{n}|^{2} + |b_{n}|^{2}){r}^{2n}. $
		\end{center} 	
		To complete the proof we need to show	
		$||f||_{\mathnormal{H}_{h}^2}= \lim_{r \rightarrow 1^{-}} M_{2} (f,r)$.
		So, from the above equation we have 
		\begin{center}
			$M_{2}^{2}(f,r)=\sum_{n=0}^{\infty} (|a_{n}|^{2} + |b_{n}|^{2}){r}^{2n}$
			               
			$ \leq \sum_{n=0}^{\infty} (|a_{n}|^{2} + |b_{n}|^{2})=||f||_{\mathnormal{H}_{h}^{2}}^{2}$,
			             
		\end{center}
		whenever $f \in {\mathnormal{H}_{h}^{2}}$ and $0 \leq r<1$.
		So $M_{2} (f,r)$ is bounded by the $\mathnormal{H}_{h}^{2}$-norm. It remains to show that whenever $\lim_{r \rightarrow 1^{-}}M_{2} (f,r)=\mathnormal{M}< \infty$, then the partial sum of the series of the form $M_{2}^{2} (f,r)=\sum_{n=0}^{\infty} (|a_{n}|^{2} + |b_{n}|^{2}){r}^{2n} $ are bounded by $\mathnormal{M^2}:$
		\begin{center}
			$\sum_{n=0}^{\mathnormal{N}} (|a_{n}|^{2} + |b_{n}|^{2}){r}^{2n} \leq \sum_{n=0}^{\infty} (|a_{n}|^{2} + |b_{n}|^{2}){r}^{2n} \leq \mathnormal{M^2}$.
		\end{center} 
		As $r \rightarrow 1^{-}$, these partial sums converges to functions in $\mathnormal{H}_{h}^{2}$, which must therefore be bounded by $\mathnormal{M^2}$ as well. If every partial sum of Taylor series representation of functions in $\mathnormal{H}_{h}^{2}$ is bounded by  $\mathnormal{M^2}$ , then this is also true for the entire series. This completes the proof.

For every complex-valued harmonic functions $f \in \mathnormal{H}_{h}^2$ on the unit disc we have 
		\begin{center}
			$||f||_{\mathnormal{H}_{h}^2}=|f(0)|^{2}+2\int_{\mathbb{D}}|f'(z)|^{2} \log \frac{1}{|z|} dA(z), $
		\end{center}
		where $d\mathnormal{A}$ denotes the normalized Lebesgue measure on $\mathbb{D}$ ($d\mathnormal{A}=\frac{1}{\pi} dxdy=\frac{1}{\pi} r dr d\theta $).

We start by	considering the right hand side of equation of Theorem 3.3., and converting $f$ into polar form, we obtain
		\begin{align*}
			|f(0)|^{2}+2\int_{\mathbb{D}}|f'(z)|^{2}\log \frac{1}{|z|} d\mathnormal{A} =|f(0)|^{2}+2\int_{-\pi}^{\pi} \frac{1}{\pi} \int_{0}^{1}|f'(re^{i\theta})|^{2} (\log \frac{1}{r})r dr d\theta
		\end{align*}
		Interchanging the two integrals which can be justified by Fubini's theorem; we have the following		    
		\begin{align*}
			|f(0)|^{2}+2\int_{\mathbb{D}}|f'(z)|^{2}\log \frac{1}{|z|} d\mathnormal{A}		
			=|f(0)|^{2}+2\int_{0}^{1} (\frac{1}{\pi} \int_{-\pi}^{\pi}|f'(re^{i\theta})|^{2} d\theta) (\log \frac{1}{r})r dr                  
		\end{align*}
		Applying simple algebraic manipulations, we obtain 	  
		\begin{align*}
			|f(0)|^{2}+2\int_{\mathbb{D}}|f'(z)|^{2}\log \frac{1}{|z|} d\mathnormal{A}=|f(0)|^{2}+4\int_{0}^{1} \mathnormal{M}_{2}^{2}(f', r) (\log \frac{1}{r})r dr
		\end{align*}
		Replacing by the Taylor series representation, we get
		\begin{align*}
			|f(0)|^{2}+2\int_{\mathbb{D}}|f'(z)|^{2}\log \frac{1}{|z|} d\mathnormal{A}
			=|f(0)|^{2}+4\int_{0}^{1} \sum_{n=1}^{\infty} (|n|^{2}|a_{n}|^{2}+ |n|^{2}|b_{n}|^{2}) r^{(2n-2)} (\log \frac{1}{r})r dr\\
			=|f(0)|^{2}+4\sum_{n=1}^{\infty} |n|^{2}(|a_{n}|^{2}+ |b_{n}|^{2}) \int_{0}^{1} r^{(2n-1)} (\log \frac{1}{r})r dr	\\
			=|f(0)|^{2}+4\sum_{n=1}^{\infty} n^{2}(|a_{n}|^{2} + |b_{n}|^{2}) \frac{1}{4n^{2}}\\
			= |f(0)|^{2}+\sum_{n=1}^{\infty} (|a_{n}|^{2}+ |b_{n}|^{2})=||f||_{\mathnormal{H}_{h}^{2}}. 	
		\end{align*}
		From which we obtain,
		$$|f(0)|^{2}+2\int_{\mathbb{D}}|f'(z)|^{2}\log \frac{1}{|z|} d\mathnormal{A}=||f||_{\mathnormal{H}_{h}^{2}}. $$	
		This completes the proof.

(Growth estimate). For each $z \in  \mathbb{D}$, the growth estimate of $f \in \mathnormal{H}_{h}^{2}$ is given by
		\begin{center}
			$|f(z)| \leq \frac{{2}||f||_{\mathnormal{H}_{h}^{2}}}{\sqrt{1-|z|^{2}}}.$
		\end{center}

(Kernel)
		The reproducing kernel function $K_{\alpha}$ , for a point $\alpha$ in $\mathbb{D}$ is defined by 
		\begin{center}
			$K_{\alpha}(z)=\frac{1}{1-\overline{\alpha}{z}}+ \frac{1}{1-\alpha \overline{z}} \hspace{2mm} $for $  |\overline{\alpha} z|<1. $
		\end{center}

For a point $\alpha \in \mathbb{D}$, $K_{\alpha}$ is the functional in  $ \mathnormal{H}_{h}^{2}(\mathbb{D})$ such that for all $f$ in $ \mathnormal{H}_{h}^{2}(\mathbb{D})$, 	we have 
		\begin{center}
			$\langle f, K_{\alpha} \rangle=f(\alpha)$
		\end{center}
		where $f$ and $K_{\alpha}$ are in $\mathnormal{H}_{h}^{2}$. Let	$f(z)=\sum_{n=0}^{\infty}a_{n}z^{n}+\sum_{n=0}^{\infty} \overline{b_{n}z^{n}}$ \hspace{0.25mm} and \hspace{0.25mm} $K_{\alpha}(z)=\sum_{n=0}^{\infty}c_{n}z^{n}+\sum_{n=0}^{\infty} \overline{d_{n}z^{n}}$  for some coefficients. Thus for each $f \in \mathnormal{H}_{h}^{2}$, 
		\begin{center}
			$\sum_{n=0}^{\infty}a_{n}\alpha^{n}+\sum_{n=0}^{\infty} \overline{b_{n}\alpha^{n}} = f(\alpha) = \langle f, K_{\alpha} \rangle = \sum_{n=0}^{\infty}a_{n}\overline{c_{n}}+\overline{b_{n}}d_{n}$.	
		\end{center}
		This implies that 
		\begin{center}
			$\sum_{n=0}^{\infty}a_{n}\alpha^{n}+\sum_{n=0}^{\infty} \overline{b_{n}} \hspace{1.5mm}\overline{\alpha^{n}} =\sum_{n=0}^{\infty}a_{n}\overline{c_{n}}+ \sum_{n=0}^{\infty}\overline{b_{n}} \hspace{1.5mm}d_{n}.$
		\end{center}
		So this can be true if the following holds true   
		\begin{center}
			$\alpha^{n}=\overline{c_{n}} $  \hspace{12mm} and \hspace{12mm} $\overline{\alpha^{n}}= d_{n} $.
		\end{center} 
		Thus,
		\begin{center}
			$K_{\alpha}(z)=\sum_{n=0}^{\infty}\overline{\alpha^{n}}{z^{n}}+\sum_{n=0}^{\infty}{\alpha^{n}} \overline{z^{n}}$
		\end{center}
		\begin{center}
			$=\sum_{n=0}^{\infty}(\overline{\alpha}z)^{n}+\sum_{n=0}^{\infty} (\alpha\overline{z})^{n}$
		\end{center}
		\begin{center}
			$=\frac{1}{1- \overline{\alpha} z}+ \frac{1}{1-\alpha \overline{z}} $ .
		\end{center}
		Therefore, the required result holds true for $|\overline{\alpha} z|<1.$
